from decimal import Decimal, InvalidOperation
from typing import Any


def _numeric(value: Any) -> Decimal:
    """Apply legacy NVL numeric behavior without binary float arithmetic."""
    if value is None or value == "":
        return Decimal(0)
    if isinstance(value, Decimal):
        return value
    if isinstance(value, float):
        return Decimal(str(value))
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        return Decimal(0)


def sweep(accounts: list[dict], orders: list[dict]) -> tuple[list[dict], list]:
    """
    Run the migrated credit-hold sweep.

    Returned account dictionaries are copies and retain input order. Processing
    and audit emission follow ACCT_MASTER primary-key (ACCT_ID) order.
    """
    new_accounts = [account.copy() for account in accounts]
    audits: list[tuple[str, Any]] = []

    # ACCT_ID is the documented ACCT_MASTER primary key.
    indexed_accounts = sorted(
        enumerate(new_accounts),
        key=lambda item: item[1].get("ACCT_ID"),
    )

    for _, account in indexed_accounts:
        if account.get("DEL_FLG") == "Y" or account.get("ACCT_TYP") != "C":
            continue

        acct_id = account.get("ACCT_ID")
        exposure = Decimal(0)

        for order in orders:
            if (
                order.get("ACCT_ID") == acct_id
                and order.get("DEL_FLG") != "Y"
                and order.get("STAT_CD") == "I"
            ):
                exposure += _numeric(order.get("TOT_AMT"))

        credit_limit = _numeric(account.get("CRED_LIMIT"))

        if exposure > credit_limit and account.get("CRED_HOLD") != "Y":
            account["CRED_HOLD"] = "Y"
            audits.append(("CRED_HOLD_ON", acct_id))

        # This is intentionally a separate IF using the value updated above.
        if exposure <= credit_limit * Decimal(8) / Decimal(10) and account.get(
            "CRED_HOLD"
        ) == "Y":
            account["CRED_HOLD"] = "N"
            audits.append(("CRED_HOLD_OFF", acct_id))

    return new_accounts, audits
